import{_ as o}from"./chunks/passcode_rescue.ByVKOyH8.js";import{_ as a,o as e,c as t,a0 as i}from"./chunks/framework.DRjqbEpm.js";const h=JSON.parse('{"title":"6. Pro 版進階功能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pro-features.md","filePath":"guide/pro-features.md"}'),l={name:"guide/pro-features.md"};function s(n,r,p,_,c,d){return e(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="_6-pro-版進階功能" tabindex="-1">6. Pro 版進階功能 <a class="header-anchor" href="#_6-pro-版進階功能" aria-label="Permalink to &quot;6. Pro 版進階功能&quot;">​</a></h1><p>免費版使用者最多可儲存 200 筆觀看紀錄（達到上限時會自動替換最舊的紀錄）。升級至 <strong>V-Train Pro</strong> 即可享受無限制的儲存空間及以下專屬功能：</p><ul><li>無限觀看紀錄與書籤儲存</li><li>解鎖完整的 Bookmark Vault (書籤庫) 管理系統</li><li>啟用影片互動面板 (按讚、截圖、快速收藏)</li><li>隱私密碼鎖設定 (Passcode)</li></ul><h3 id="如何啟用-pro" tabindex="-1">如何啟用 Pro？ <a class="header-anchor" href="#如何啟用-pro" aria-label="Permalink to &quot;如何啟用 Pro？&quot;">​</a></h3><ol><li>在控制面板點擊下方的 <strong>「⚡ Unlock V-Train Pro」</strong>。</li><li>貼上您購買時獲得的授權序號。</li><li>驗證成功後，面板會顯示「V-Train Pro 已啟用」，並解鎖所有功能！</li></ol><h3 id="密碼忘記怎麼辦-救援解鎖" tabindex="-1">密碼忘記怎麼辦？ (救援解鎖) <a class="header-anchor" href="#密碼忘記怎麼辦-救援解鎖" aria-label="Permalink to &quot;密碼忘記怎麼辦？ (救援解鎖)&quot;">​</a></h3><p>如果您忘記了隱私密碼，點擊鎖定畫面的 <strong>「Forgot Passcode?」</strong>。</p><blockquote><p><img src="'+o+'" alt="密碼救援"> 輸入您的 Pro 授權序號進行驗證，成功後密碼將被重置並清除。建議解鎖後立即進行一次完整備份！</p></blockquote>',8)])])}const m=a(l,[["render",s]]);export{h as __pageData,m as default};
